import { defineConfig } from 'vite'
import react from '@vitejs/plugin-react'

export default defineConfig({
  plugins: [react()],
  server: {
    port: 5173,
    proxy: {
      '/api': 'http://localhost:8000'
    }
  }
})

const BASE = '/api'

async function handle(res) {
  if (!res.ok) {
    let msg = `HTTP ${res.status}`
    try {
      const data = await res.json()
      if (data?.detail) msg = typeof data.detail === 'string' ? data.detail : JSON.stringify(data.detail)
    } catch {}
    throw new Error(msg)
  }
  if (res.status === 204) return null
  return res.json()
}

export const api = {
  list: (status) => {
    const qs = status ? `?status=${encodeURIComponent(status)}` : ''
    return fetch(`${BASE}/books${qs}`).then(handle)
  },
  create: (book) =>
    fetch(`${BASE}/books`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(book),
    }).then(handle),
  update: (id, patch) =>
    fetch(`${BASE}/books/${id}`, {
      method: 'PATCH',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(patch),
    }).then(handle),
  remove: (id) =>
    fetch(`${BASE}/books/${id}`, { method: 'DELETE' }).then(handle),
}

import { useEffect, useState } from 'react'
import { api } from './api'

const STATUSES = [
  { value: 'to-read', label: 'Da leggere' },
  { value: 'reading', label: 'In lettura' },
  { value: 'done', label: 'Letto' },
]

const STATUS_LABEL = Object.fromEntries(STATUSES.map(s => [s.value, s.label]))

export default function App() {
  const [books, setBooks] = useState([])
  const [filter, setFilter] = useState('')
  const [title, setTitle] = useState('')
  const [author, setAuthor] = useState('')
  const [status, setStatus] = useState('to-read')
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState(null)

  async function load() {
    setLoading(true)
    setError(null)
    try {
      const data = await api.list(filter || undefined)
      setBooks(data)
    } catch (e) {
      setError(e.message)
    } finally {
      setLoading(false)
    }
  }

  useEffect(() => { load() }, [filter])

  async function handleAdd(e) {
    e.preventDefault()
    if (!title.trim() || !author.trim()) return
    try {
      await api.create({ title: title.trim(), author: author.trim(), status })
      setTitle(''); setAuthor(''); setStatus('to-read')
      load()
    } catch (e) { setError(e.message) }
  }

  async function handleStatus(book, newStatus) {
    try {
      await api.update(book.id, { status: newStatus })
      setBooks(bs => bs.map(b => b.id === book.id ? { ...b, status: newStatus } : b))
      if (filter && filter !== newStatus) {
        setBooks(bs => bs.filter(b => b.id !== book.id))
      }
    } catch (e) { setError(e.message) }
  }

  async function handleDelete(id) {
    if (!confirm('Eliminare questo libro?')) return
    try {
      await api.remove(id)
      setBooks(bs => bs.filter(b => b.id !== id))
    } catch (e) { setError(e.message) }
  }

  const counts = books.reduce((acc, b) => { acc[b.status] = (acc[b.status]||0)+1; return acc }, {})

  return (
    <div className="container">
      <header>
        <h1>📚 BookTrack</h1>
        <p className="sub">La mia libreria personale</p>
      </header>

      <section className="card">
        <h2>Aggiungi libro</h2>
        <form onSubmit={handleAdd} className="form">
          <input
            placeholder="Titolo"
            value={title}
            onChange={e => setTitle(e.target.value)}
            required
          />
          <input
            placeholder="Autore"
            value={author}
            onChange={e => setAuthor(e.target.value)}
            required
          />
          <select value={status} onChange={e => setStatus(e.target.value)}>
            {STATUSES.map(s => <option key={s.value} value={s.value}>{s.label}</option>)}
          </select>
          <button type="submit">Aggiungi</button>
        </form>
      </section>

      <section className="card">
        <div className="toolbar">
          <h2>Lista {filter ? `(${STATUS_LABEL[filter]})` : ''}</h2>
          <div className="filters">
            <button
              className={!filter ? 'chip active' : 'chip'}
              onClick={() => setFilter('')}
            >Tutti</button>
            {STATUSES.map(s => (
              <button
                key={s.value}
                className={filter === s.value ? 'chip active' : 'chip'}
                onClick={() => setFilter(s.value)}
              >{s.label}</button>
            ))}
          </div>
        </div>

        {error && <div className="error">⚠ {error}</div>}
        {loading && <div className="muted">Caricamento…</div>}
        {!loading && books.length === 0 && <div className="muted">Nessun libro.</div>}

        <ul className="books">
          {books.map(b => (
            <li key={b.id} className={`book status-${b.status}`}>
              <div className="book-info">
                <div className="book-title">{b.title}</div>
                <div className="book-author">{b.author}</div>
              </div>
              <div className="book-actions">
                <select
                  value={b.status}
                  onChange={e => handleStatus(b, e.target.value)}
                >
                  {STATUSES.map(s => <option key={s.value} value={s.value}>{s.label}</option>)}
                </select>
                <button className="danger" onClick={() => handleDelete(b.id)}>×</button>
              </div>
            </li>
          ))}
        </ul>

        {!filter && books.length > 0 && (
          <div className="counts">
            {STATUSES.map(s => (
              <span key={s.value}>{s.label}: <b>{counts[s.value] || 0}</b></span>
            ))}
          </div>
        )}
      </section>
    </div>
  )
}

* { box-sizing: border-box; }
body {
  margin: 0;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  background: #f4f5f7;
  color: #1f2933;
}
.container {
  max-width: 760px;
  margin: 0 auto;
  padding: 2rem 1rem 4rem;
}
header h1 { margin: 0; font-size: 2rem; }
header .sub { margin: .25rem 0 1.5rem; color: #6b7280; }

.card {
  background: #fff;
  border-radius: 12px;
  padding: 1.25rem 1.25rem 1.5rem;
  box-shadow: 0 1px 3px rgba(0,0,0,.06);
  margin-bottom: 1.25rem;
}
.card h2 { margin: 0 0 .9rem; font-size: 1.1rem; }

.form {
  display: grid;
  grid-template-columns: 1fr 1fr auto auto;
  gap: .5rem;
}
.form input, .form select, select, button {
  padding: .55rem .75rem;
  border: 1px solid #d1d5db;
  border-radius: 8px;
  font-size: .95rem;
  background: #fff;
}
button {
  cursor: pointer;
  background: #2563eb;
  color: white;
  border-color: #2563eb;
  transition: background .15s;
}
button:hover { background: #1d4ed8; }
button.danger {
  background: transparent;
  color: #b91c1c;
  border-color: #fca5a5;
  padding: .35rem .55rem;
  font-size: 1.1rem;
  line-height: 1;
}
button.danger:hover { background: #fee2e2; }

.toolbar {
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: .5rem;
  margin-bottom: .9rem;
}
.filters { display: flex; gap: .35rem; flex-wrap: wrap; }
.chip {
  background: #eef2f7;
  color: #374151;
  border: 1px solid #e5e7eb;
  padding: .3rem .7rem;
  font-size: .85rem;
  border-radius: 999px;
}
.chip:hover { background: #e5e7eb; }
.chip.active {
  background: #2563eb;
  color: #fff;
  border-color: #2563eb;
}

.books { list-style: none; padding: 0; margin: 0; }
.book {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: .75rem;
  padding: .75rem .9rem;
  border: 1px solid #eef0f3;
  border-left: 4px solid #d1d5db;
  border-radius: 8px;
  margin-bottom: .5rem;
  background: #fafbfc;
}
.book.status-to-read { border-left-color: #9ca3af; }
.book.status-reading { border-left-color: #f59e0b; background: #fffbeb; }
.book.status-done    { border-left-color: #10b981; }
.book.status-done .book-title { text-decoration: line-through; color: #6b7280; }

.book-info { min-width: 0; flex: 1; }
.book-title { font-weight: 600; word-break: break-word; }
.book-author { color: #6b7280; font-size: .9rem; }
.book-actions { display: flex; gap: .4rem; align-items: center; }
.book-actions select { padding: .35rem .5rem; font-size: .85rem; }

.muted { color: #6b7280; font-size: .9rem; }
.error {
  background: #fef2f2;
  color: #991b1b;
  border: 1px solid #fecaca;
  padding: .5rem .75rem;
  border-radius: 8px;
  margin-bottom: .75rem;
  font-size: .9rem;
}
.counts {
  display: flex;
  gap: 1rem;
  flex-wrap: wrap;
  margin-top: 1rem;
  padding-top: .75rem;
  border-top: 1px solid #eef0f3;
  font-size: .85rem;
  color: #6b7280;
}

@media (max-width: 560px) {
  .form { grid-template-columns: 1fr 1fr; }
  .form button { grid-column: span 2; }
}
